pub fn solve(n: i8, k: i8) -> i8 {
    // Compute the nonnegative remainder r = n mod k.
    // Since n >= 0 and k > 0, n.rem_euclid(k) will be in [0, k-1].
    let r = n.rem_euclid(k);

    // The distance to the next multiple of k is (k - r).
    // We want the minimal nonnegative distance, so take the min of r and k-r.
    let complement = k - r;

    if r < complement {
        r
    } else {
        complement
    }
}

